-- Softema Hub: two-factor authentication, team invitations and member management.
-- Runs as the owner role. The Prisma part was generated by `prisma migrate diff`; the drift it also reports
-- (contact_search_idx, contact.search_text) comes from the hand-written part of 0001 and is intentionally left out.

-- AlterTable
ALTER TABLE "hub"."user" ADD COLUMN     "twoFactorEnabled" BOOLEAN DEFAULT false;

-- CreateTable
CREATE TABLE "hub"."twoFactor" (
    "id" TEXT NOT NULL,
    "secret" TEXT NOT NULL,
    "backupCodes" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "verified" BOOLEAN DEFAULT true,
    "failedVerificationCount" INTEGER DEFAULT 0,
    "lockedUntil" TIMESTAMPTZ,

    CONSTRAINT "twoFactor_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "hub"."invitation" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "workspace_id" UUID NOT NULL,
    "email" TEXT NOT NULL,
    "email_normalized" TEXT NOT NULL,
    "role" "hub"."WorkspaceRole" NOT NULL,
    "token_hash" TEXT NOT NULL,
    "invited_by_user_id" TEXT,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ NOT NULL,
    "accepted_at" TIMESTAMPTZ,
    "accepted_by_user_id" TEXT,
    "revoked_at" TIMESTAMPTZ,

    CONSTRAINT "invitation_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "twoFactor_userId_idx" ON "hub"."twoFactor"("userId");

-- CreateIndex
CREATE UNIQUE INDEX "invitation_token_hash_key" ON "hub"."invitation"("token_hash");

-- CreateIndex
CREATE INDEX "invitation_workspace_id_created_at_idx" ON "hub"."invitation"("workspace_id", "created_at" DESC);

-- AddForeignKey
ALTER TABLE "hub"."twoFactor" ADD CONSTRAINT "twoFactor_userId_fkey" FOREIGN KEY ("userId") REFERENCES "hub"."user"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "hub"."invitation" ADD CONSTRAINT "invitation_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "hub"."workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "hub"."invitation" ADD CONSTRAINT "invitation_invited_by_user_id_fkey" FOREIGN KEY ("invited_by_user_id") REFERENCES "hub"."user"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ===== Everything below is hand-written: what Prisma cannot express =====

-- ---------- grants: identity ----------
-- The TOTP secret and backup codes are for the auth role only.
GRANT SELECT, INSERT, UPDATE, DELETE ON hub."twoFactor" TO hub_auth;
-- The application may show whether a team member has 2FA, never the secret.
GRANT SELECT ("twoFactorEnabled") ON hub."user" TO hub_app;

-- ---------- role of the user in the context ----------
-- Like has_workspace_access: SECURITY DEFINER, always answers for the user in the context, never for a caller-supplied user.
CREATE FUNCTION hub.workspace_role(ws uuid) RETURNS text
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT CASE
      WHEN EXISTS (SELECT 1 FROM hub.workspace w JOIN hub.agency_membership a ON a.agency_id = w.agency_id WHERE w.id = ws AND a.user_id = hub.current_user_id()) THEN 'agency_admin'
      ELSE (SELECT m.role::text FROM hub.workspace_membership m WHERE m.workspace_id = ws AND m.user_id = hub.current_user_id())
    END
  $$;
CREATE FUNCTION hub.is_workspace_admin(ws uuid) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$ SELECT coalesce(hub.workspace_role(ws) IN ('agency_admin', 'workspace_admin'), false) $$;

-- ---------- invitations: read ----------
-- RLS is enabled but not FORCEd: the table is written only by the owner-run functions below.
-- The application role reads pending invitations of a workspace it administers, never the token hash.
ALTER TABLE hub.invitation ENABLE ROW LEVEL SECURITY;
GRANT SELECT (id, workspace_id, email, role, invited_by_user_id, created_at, expires_at, accepted_at, revoked_at) ON hub.invitation TO hub_app;
CREATE POLICY invitation_admin_read ON hub.invitation FOR SELECT TO hub_app
  USING (workspace_id = hub.current_workspace_id() AND hub.is_workspace_admin(workspace_id));

-- ---------- membership changes ----------
-- The application role still has no INSERT/UPDATE/DELETE on membership tables. Every change goes through a function
-- that checks the caller's role in the database, so a bug or a missing check in the API cannot grant access.
-- Functions return a status instead of raising, so the API can answer with a precise error.

CREATE FUNCTION hub.invite_member(ws uuid, p_email text, p_role hub."WorkspaceRole", p_token_hash text, p_expires_at timestamptz) RETURNS jsonb
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
  AS $$
  DECLARE
    norm text := lower(btrim(p_email));
    new_id uuid;
  BEGIN
    IF NOT hub.is_workspace_admin(ws) THEN RETURN jsonb_build_object('status', 'forbidden'); END IF;
    IF EXISTS (SELECT 1 FROM hub.workspace_membership m JOIN hub."user" u ON u.id = m.user_id WHERE m.workspace_id = ws AND lower(u.email) = norm) THEN
      RETURN jsonb_build_object('status', 'already_member');
    END IF;
    -- A new invitation replaces a pending one for the same address, so only the latest link works.
    UPDATE hub.invitation SET revoked_at = now() WHERE workspace_id = ws AND email_normalized = norm AND accepted_at IS NULL AND revoked_at IS NULL;
    INSERT INTO hub.invitation (workspace_id, email, email_normalized, role, token_hash, invited_by_user_id, expires_at)
      VALUES (ws, btrim(p_email), norm, p_role, p_token_hash, hub.current_user_id(), p_expires_at)
      RETURNING id INTO new_id;
    RETURN jsonb_build_object('status', 'ok', 'id', new_id);
  END
  $$;

CREATE FUNCTION hub.revoke_invitation(ws uuid, p_id uuid) RETURNS text
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
  AS $$
  BEGIN
    IF NOT hub.is_workspace_admin(ws) THEN RETURN 'forbidden'; END IF;
    UPDATE hub.invitation SET revoked_at = now() WHERE id = p_id AND workspace_id = ws AND accepted_at IS NULL AND revoked_at IS NULL;
    RETURN CASE WHEN FOUND THEN 'ok' ELSE 'not_found' END;
  END
  $$;

CREATE FUNCTION hub.set_member_role(ws uuid, p_user_id text, p_role hub."WorkspaceRole") RETURNS text
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
  AS $$
  BEGIN
    IF NOT hub.is_workspace_admin(ws) THEN RETURN 'forbidden'; END IF;
    -- Nobody can lock themselves out or promote themselves.
    IF p_user_id = hub.current_user_id() THEN RETURN 'self'; END IF;
    UPDATE hub.workspace_membership SET role = p_role WHERE workspace_id = ws AND user_id = p_user_id;
    RETURN CASE WHEN FOUND THEN 'ok' ELSE 'not_found' END;
  END
  $$;

CREATE FUNCTION hub.remove_member(ws uuid, p_user_id text) RETURNS text
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
  AS $$
  BEGIN
    IF NOT hub.is_workspace_admin(ws) THEN RETURN 'forbidden'; END IF;
    IF p_user_id = hub.current_user_id() THEN RETURN 'self'; END IF;
    DELETE FROM hub.workspace_membership WHERE workspace_id = ws AND user_id = p_user_id;
    RETURN CASE WHEN FOUND THEN 'ok' ELSE 'not_found' END;
  END
  $$;

-- ---------- accepting an invitation ----------
-- Possession of the token is the credential: only its hash is compared, and only pending, unexpired invitations answer.
CREATE FUNCTION hub.invitation_preview(p_token_hash text)
  RETURNS TABLE (workspace_id uuid, workspace_name text, email text, email_normalized text, role hub."WorkspaceRole", account_exists boolean)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT i.workspace_id, w.name, i.email, i.email_normalized, i.role,
           EXISTS (SELECT 1 FROM hub."user" u WHERE lower(u.email) = i.email_normalized)
      FROM hub.invitation i JOIN hub.workspace w ON w.id = i.workspace_id
     WHERE i.token_hash = p_token_hash AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()
  $$;

-- Accepts for the user in the context. The invitation is locked, so it can be used exactly once.
CREATE FUNCTION hub.accept_invitation(p_token_hash text) RETURNS jsonb
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = ''
  AS $$
  DECLARE
    inv hub.invitation%ROWTYPE;
    me text := hub.current_user_id();
  BEGIN
    IF me IS NULL THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
    SELECT * INTO inv FROM hub.invitation
     WHERE token_hash = p_token_hash AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at > now()
     FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
    IF NOT EXISTS (SELECT 1 FROM hub."user" u WHERE u.id = me AND lower(u.email) = inv.email_normalized) THEN
      RETURN jsonb_build_object('status', 'email_mismatch');
    END IF;
    -- An existing membership keeps its role: an invitation never silently changes what someone already has.
    INSERT INTO hub.workspace_membership (workspace_id, user_id, role) VALUES (inv.workspace_id, me, inv.role)
      ON CONFLICT (workspace_id, user_id) DO NOTHING;
    UPDATE hub.invitation SET accepted_at = now(), accepted_by_user_id = me WHERE id = inv.id;
    RETURN jsonb_build_object('status', 'ok', 'workspace_id', inv.workspace_id);
  END
  $$;

DO $$
DECLARE f text;
BEGIN
  FOREACH f IN ARRAY ARRAY[
    'hub.workspace_role(uuid)', 'hub.is_workspace_admin(uuid)',
    'hub.invite_member(uuid, text, hub."WorkspaceRole", text, timestamptz)', 'hub.revoke_invitation(uuid, uuid)',
    'hub.set_member_role(uuid, text, hub."WorkspaceRole")', 'hub.remove_member(uuid, text)',
    'hub.invitation_preview(text)', 'hub.accept_invitation(text)'
  ] LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO hub_app', f);
  END LOOP;
END $$;
